int cubalc_help_catalog_n(void) {
  return (int)(sizeof cubalc_help_catalog / sizeof cubalc_help_catalog[0]);
}
/* Exact case-insensitive form name match (ignores multi-word SYS X entries unless full). */
int cubalc_form_known(const char *want, const char **hint_out) {
  char q[96]; size_t i, n; int k, nhelp;
  if (!want || !want[0]) return 0;
  for (i = 0; want[i] && i + 1 < sizeof q; i++) {
    char c = want[i];
    if (c >= 'a' && c <= 'z') c = (char)(c - 'a' + 'A');
    q[i] = c;
  }
  q[i] = 0;
  nhelp = cubalc_help_catalog_n();
  for (k = 0; k < nhelp; k++) {
    char nm[96];
    const char *hn = cubalc_help_catalog[k].name;
    for (n = 0; hn[n] && n + 1 < sizeof nm; n++) {
      char c = hn[n];
      if (c >= 'a' && c <= 'z') c = (char)(c - 'a' + 'A');
      nm[n] = c;
    }
    nm[n] = 0;
    if (strcmp(nm, q) == 0) {
      if (hint_out) *hint_out = cubalc_help_catalog[k].hint;
      return 1;
    }
  }
  return 0;
}

